    for (int i = 1; i <= 3; i++) head = push(head, i);
    for (Node *p = head; p; p = p->next) printf("%d ", p->value);
    printf("\n");
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

